#include "../Includes/obfuscate.h"
#include "../Includes/Logger.h"
#include "../Includes/Utils.hpp"
#include "Menu/Menu.hpp"

void Init(JNIEnv *env, jobject thiz, jobject ctx, jobject title, jobject bottomTitle){
    Menu::setText(env, title, OBFUSCATE("R3D NETWORK ID"));
    Menu::setText(env, bottomTitle, OBFUSCATE("Modded by rrosetta | Platinmods.com"));

    Menu::showToast(env,ctx,OBFUSCATE("R3D Network ID"),ToastLength::LENGTH_LONG);

    // Set Colored Toast
    //Menu::showToast(env,ctx,OBFUSCATE("<b><font color=lime>Modded by Nik2143 - Exclusive on www.Platinmods.com</font></b>"),ToastLength::LENGTH_LONG);
}

/* Image shown on the floating bubble, as a base64 encoded PNG/JPG (a "data:image/...;base64," prefix is fine).
 * It is drawn cropped to a circle, a square image of about 128x128 or larger looks best.
 * Leave it empty to draw Theme.BUBBLE_TEXT instead.
 * Use https://www.base64encode.org/ or `base64 -i icon.png` to encode your image.
 */
jstring Icon(JNIEnv *env, jobject thiz) {
    return env->NewStringUTF(OBFUSCATE(""));
}

int RegisterMenu(JNIEnv *env) {
    jclass clazz = env->FindClass(OBFUSCATE("com/android/support/Menu"));
    if (!clazz) {
        LOGE(OBFUSCATE("Menu class not found"));
        return JNI_ERR; // Class not found
    }

    static const JNINativeMethod methods[] = {
            {OBFUSCATE("Init")              , OBFUSCATE("(Landroid/content/Context;Landroid/widget/TextView;Landroid/widget/TextView;)V")   , reinterpret_cast<void *>(Init)},
            {OBFUSCATE("Icon")              , OBFUSCATE("()Ljava/lang/String;")                                                              , reinterpret_cast<void *>(Icon)},
    };

    jint ret = env->RegisterNatives(clazz, methods, sizeof(methods) / sizeof(JNINativeMethod));
    if (ret != JNI_OK) {
        return ret; // Failed to register natives
    }

    LOGI(OBFUSCATE("Menu registered"));
    return JNI_OK;
}


